38	
39		public bool useSimpleInfo;
40	
41		protected virtual string ExtraInfo => string.Empty;
42	
43		public virtual string FormattedExtraInfo
44		{
45			get
46			{
47				string result;
48				if (ExtraInfo == string.Empty)
49				{
50					result = string.Empty;
51				}
52				else
53				{
54					result = ((!useSimpleInfo) ? ("\n<color=#009999>( </color><color=#00dddd>" + ExtraInfo + "</color><color=#009999> )</color>") : ("\n<color=#00dddd>" + ExtraInfo + "</color>"));
55				}
56				return result;
57			}
58		}
59	
60		public Item()
61		{
62		}
