79		{
80		}
81	
82		public bool GroupItemCreated(string givenID)
83		{
84			if (SetParentAsPlayer() && !parentPlayer.inventory.ContainsItem(givenID) && GroupItemManager.groupsDict.ContainsKey(givenID) && GroupItemManager.groupsDict[givenID].Contains(ID))
85			{
86				foreach (string item in GroupItemManager.groupsDict[givenID])
87				{
88					if (item != ID && parentPlayer.inventory.ContainsItem(item))
89					{
90						parentPlayer.inventory.AddItem(givenID, showNotice: false, ignoreMax: true);
91						return true;
92					}
93				}
94			}
95			return false;
96		}
