138		{
139			if (setUnlocked)
140			{
141				if (!GameDataManager.gameData.CheckItemDataEntry(givenID))
142				{
143					GameDataManager.gameData.UpdateItemDataEntry(givenID);
144					GameDataManager.Save();
145					AchievementManager.UnlockAchievement(Achievement.UnlockHalfRelics);
