344		private void SetEventHandlers(bool givenStatus)
345		{
346			if ((!givenStatus || !GroupItemCreated(OnBasicUseGroupItem.staticID)) && SetParentAsPlayer())
347			{
348				Player player = parentPlayer;
349				player.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new Player.SkillEventHandler(OnSkillExec));
350				if (givenStatus)
351				{
352					Player player2 = parentPlayer;
353					player2.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillExecEventHandlers, new Player.SkillEventHandler(OnSkillExec));
354				}
355			}
356		}
357	
358		private void OnSkillExec(Player.SkillState givenState)
359		{
360			currentState = givenState as Player.MeleeAttackState;
361			if (CheckActivationChance(currentState))
362			{
363				CreateItemEffect(currentState);
364			}
365		}
366	
367		public virtual bool CheckActivationChance(Player.MeleeAttackState givenState)
368		{
369			return givenState != null && UnityEngine.Random.value < activationChance / ((float)givenState.maxComboCount + 0.5f);
370		}
371	
372		public virtual void CreateItemEffect(Player.MeleeAttackState givenState)
373		{
374			currentPosition = parentPlayer.transform.position;
375			currentAtkPosition = parentPlayer.attackOriginTrans.position;
376			currentVector = givenState.inputVector;
377		}
378	}
