584		private void SetEventHandlers(bool givenStatus)
585		{
586			SetModStatus(givenStatus);
587			GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Remove(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
588			if (givenStatus)
589			{
590				GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Combine(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoad));
591			}
592		}
