594		private void OnLevelLoad(string a, string b)
595		{
596			SetModStatus(givenStatus: true);
597		}
598	
599		private void SetModStatus(bool givenStatus)
600		{
601			if (preventTypes == null)
602			{
603				return;
604			}
605			if (givenStatus)
606			{
607				if (!inEffect.CurrentValue)
608				{
609					inEffect.AddMod(preventSkillMod);
610					for (int i = 0; i < preventTypes.Length; i++)
611					{
612						Enemy.PreventSkills(preventTypes[i], preventSkillMod, givenStatus: true);
613					}
614				}
