	Player[] activePlayers = GameController.activePlayers;
	foreach (Player player in activePlayers)
	{
		if (!(player == null))
		{
			player.health.ignoreBurn.Modify(ignoreMod, givenStatus);
			player.health.ignoreSlow.Modify(ignoreMod, givenStatus);
			player.health.ignorePoison.Modify(ignoreMod, givenStatus);
			player.health.ignoreShock.Modify(ignoreMod, givenStatus);
			player.health.ignoreFreeze.Modify(ignoreMod, givenStatus);
			StatManager.ModifyAllStatData(damageMod, player.skillCategory, "damage", IgnoreStatusConditional, givenStatus);
		}
	}
	Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Remove(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
	if (givenStatus)
	{
		Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Combine(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
	}
	StatManager.ModifyAllStatData(damageMod, Enemy.globalEnemySkillCategory, "damage", IgnoreStatusAndHazard, givenStatus);
	for (int j = 0; j < GameController.enemies.Count; j++)
	{
		if (GameController.enemies[j] != null)
		{
			ApplyModToEnemy(GameController.enemies[j].GetComponent<Enemy>(), givenStatus);
		}
	}
}
private void OnEnemySpawn(Enemy givenEnemy)
{
	ApplyModToEnemy(givenEnemy, givenStatus: true);
}
private void ApplyModToEnemy(Enemy givenEnemy, bool givenStatus)
{
	if (givenEnemy != null && givenEnemy.health != null)
	{
		givenEnemy.health.ignoreBurn.Modify(ignoreMod, givenStatus);
		givenEnemy.health.ignoreSlow.Modify(ignoreMod, givenStatus);
		givenEnemy.health.ignorePoison.Modify(ignoreMod, givenStatus);
		givenEnemy.health.ignoreShock.Modify(ignoreMod, givenStatus);
		givenEnemy.health.ignoreFreeze.Modify(ignoreMod, givenStatus);
	}
}
private bool IgnoreStatusAndHazard(StatData givenSD)
{
	return givenSD != null && !givenSD.GetValue<bool>("isStatusEffect");
}
